import React, { useEffect, useState } from "react"
import { Link } from "react-router-dom";
import { useSelector, useDispatch } from "react-redux";

import { ibg } from "../../utils/ibg";
import { addItem, selectCartItemById } from '../../redux/slices/cart/cartSlice';
import { CartItem } from "../../redux/slices/cart/types";



type PizzaBlockProps = {
    id: string;
    title: string;
    price: number;
    image: string;
    sizes: number[];
    types: number[];
}


export const PizzaBlock: React.FC<PizzaBlockProps> = ({ id, title, price, image, sizes, types }) => {
    const dispatch = useDispatch()

    // const cartItem = useSelector((state) => state.cart.items.find(obj => obj.id === id))
    const cartItem = useSelector(selectCartItemById(id))

    const typesNames = ['тонке', 'традиційне'];
    const [activeType, setActiveType] = useState(0);
    const [activeSize, setActiveSize] = useState(0);

    const addedCount = cartItem ? cartItem.count : 0

    useEffect(() => {
        ibg()
    }, [])

    const onClickAdd = () => {
        const item: CartItem = {
            id: id,
            title: title,
            price: price,
            image: image,
            type: typesNames[activeType],
            size: sizes[activeSize],
            count: 0
        }
        dispatch(addItem(item))
    }
    return (
        <div className="pizza-block">
            <Link to={`/pizza/${id}`}>
                <div className="pizza-block-image ibg">
                    <img
                        className="pizza-block__image"
                        src={`${process.env.PUBLIC_URL}/${image}`}
                        alt="Піца"
                    />
                </div>
            </Link>
            <div className="pizza-block-inner">
                <h4 className="pizza-block__title">{title}</h4>
                <div className="pizza-block__selector">
                    <ul>
                        {types.map((item, i) => {
                            return <li key={i} onClick={() => setActiveType(i)} className={activeType === i ? 'active' : ''}>{typesNames[item]}</li>
                        })}
                    </ul>
                    <ul>
                        {sizes.map((item, i) => {
                            return <li key={i} onClick={() => setActiveSize(i)} className={activeSize === i ? 'active' : ''}>{item} см</li>
                        })}
                    </ul>
                </div>
                <div className="pizza-block__bottom">
                    <div className="pizza-block__price">від {price} ₴</div>
                    <button className="button button--outline button--add" onClick={onClickAdd}>
                        <svg
                            width="12"
                            height="12"
                            viewBox="0 0 12 12"
                            fill="none"
                            xmlns="http://www.w3.org/2000/svg"
                        >
                            <path
                                d="M10.8 4.8H7.2V1.2C7.2 0.5373 6.6627 0 6 0C5.3373 0 4.8 0.5373 4.8 1.2V4.8H1.2C0.5373 4.8 0 5.3373 0 6C0 6.6627 0.5373 7.2 1.2 7.2H4.8V10.8C4.8 11.4627 5.3373 12 6 12C6.6627 12 7.2 11.4627 7.2 10.8V7.2H10.8C11.4627 7.2 12 6.6627 12 6C12 5.3373 11.4627 4.8 10.8 4.8Z"
                                fill="white"
                            />
                        </svg>
                        <span >Додати</span>
                        <i > {addedCount}</i>
                    </button>
                </div>
            </div>
        </div >
    )
}